const body = $json.body ?? $json;
const email = typeof body.caption_email === 'string' ? body.caption_email.trim().toLowerCase() : '';
const emailPattern = /^[a-zA-Z0-9.!#$%&'*+\/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)+$/;
if (!body.processing_id || !body.message_id || body.source !== 'whatsapp') throw new Error('Invalid WhatsApp event identity');
if (!emailPattern.test(email)) throw new Error('A valid email caption is required');
if (!body.image || !['image/jpeg', 'image/png', 'image/webp'].includes(body.image.mime_type) || typeof body.image.base64 !== 'string' || body.image.base64.length === 0) throw new Error('A valid image payload is required');
return [{ json: { ...body, caption_email: email } }];

const original = $('Validate Event').first().json;
const ocrResult = $json;
const fields = ocrResult.fields ?? {};
const ocrEmail = typeof fields.email === 'string' ? fields.email.trim().toLowerCase() : '';
const minutes = fields.minutes == null ? null : Number.parseInt(String(fields.minutes), 10);
const paymentHour = fields.payment_hour == null ? null : Number.parseInt(String(fields.payment_hour), 10);
const dateValid = typeof fields.payment_date === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(fields.payment_date);
const emailConflict = Boolean(ocrEmail) && ocrEmail !== original.caption_email;
const evidenceReady = Number.isInteger(fields.amount_cents) && dateValid && Number.isInteger(minutes) && minutes >= 0 && minutes <= 59 && !emailConflict;
let verification = null;
if (original.stripe_verification_enabled !== true) verification = { status: 'SKIPPED', verdict: 'UNCLEAR', reason_code: 'STRIPE_DISABLED' };
else if (emailConflict) verification = { status: 'NO_MATCH', verdict: 'UNCLEAR', reason_code: 'CAPTION_OCR_EMAIL_CONFLICT' };
else if (!evidenceReady) verification = { status: 'NO_MATCH', verdict: 'UNCLEAR', reason_code: 'INSUFFICIENT_OCR_EVIDENCE' };
return [{ json: { processing_id: original.processing_id, ready_for_stripe: original.stripe_verification_enabled === true && evidenceReady, ocr_result: ocrResult, verification, stripe_request: { processing_id: original.processing_id, email: original.caption_email, amount_cents: fields.amount_cents, payment_date: fields.payment_date, minutes, payment_hour: Number.isInteger(paymentHour) ? paymentHour : null, currency: 'usd', payment_method_type: 'cashapp' } } }];
